import sys
input = sys.stdin.read

def smallest_xor_sum(a, b):
    return a + b - 2 * (a & b)

def main():
    data = input().split()
    idx = 0
    t = int(data[idx])
    idx += 1
    results = []
    for _ in range(t):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        results.append(smallest_xor_sum(a, b))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

